mapper.select:
select report_amounts.*, (report_amounts.sales_amount - report_amounts.sales_cost) as gross_margin from ( select report_base.stock_item_count, report_base.warning_stock_count, report_base.missing_safety_stock_count, report_base.zero_stock_count, report_base.total_stock_cost, report_base.purchase_order_count, (report_base.purchase_received_amount - report_base.purchase_return_amount) as purchase_amount, report_base.sales_order_count, (report_base.sales_delivered_amount - report_base.sales_return_amount) as sales_amount, (report_base.sales_out_cost - report_base.sales_return_cost) as sales_cost from ( select ( select count(1) from inv_stock s left join inv_product p on p.product_id = s.product_id and p.del_flag = '0'
) as stock_item_count, ( select coalesce(sum(case when coalesce(p.safety_stock_min, 0) > 0 and coalesce(s.available_quantity, s.current_quantity, 0) <= p.safety_stock_min then 1 else 0 end), 0) from inv_stock s left join inv_product p on p.product_id = s.product_id and p.del_flag = '0'
) as warning_stock_count, ( select coalesce(sum(case when coalesce(p.safety_stock_min, 0) <= 0 then 1 else 0 end), 0) from inv_stock s left join inv_product p on p.product_id = s.product_id and p.del_flag = '0'
) as missing_safety_stock_count, ( select coalesce(sum(case when coalesce(s.available_quantity, s.current_quantity, 0) <= 0 then 1 else 0 end), 0) from inv_stock s left join inv_product p on p.product_id = s.product_id and p.del_flag = '0'
) as zero_stock_count, ( select coalesce(sum(s.total_cost), 0) from inv_stock s left join inv_product p on p.product_id = s.product_id and p.del_flag = '0'
) as total_stock_cost, ( select count(distinct o.order_id) from inv_purchase_order o inner join inv_purchase_detail d on d.order_id = o.order_id left join inv_product p on p.product_id = d.product_id and p.del_flag = '0' left join inv_product_category c on c.category_id = p.category_id and c.del_flag = '0'
o.status in ('submitted', 'received') and coalesce(d.received_quantity, 0) > 0
) as purchase_order_count, ( select coalesce(sum(coalesce(d.received_quantity, 0) * coalesce(d.unit_price, 0)), 0) from inv_purchase_order o inner join inv_purchase_detail d on d.order_id = o.order_id left join inv_product p on p.product_id = d.product_id and p.del_flag = '0' left join inv_product_category c on c.category_id = p.category_id and c.del_flag = '0'
o.status in ('submitted', 'received') and coalesce(d.received_quantity, 0) > 0
) as purchase_received_amount, ( select coalesce(sum(coalesce(d.returned_quantity, 0) * coalesce(d.unit_price, 0)), 0) from inv_purchase_return r inner join inv_purchase_return_detail d on d.return_id = r.return_id left join inv_product p on p.product_id = d.product_id and p.del_flag = '0' left join inv_product_category c on c.category_id = p.category_id and c.del_flag = '0'
r.status = 'returned' and coalesce(d.returned_quantity, 0) > 0
) as purchase_return_amount, ( select count(distinct o.order_id) from inv_sales_order o inner join inv_sales_detail d on d.order_id = o.order_id left join inv_product p on p.product_id = d.product_id and p.del_flag = '0' left join inv_product_category c on c.category_id = p.category_id and c.del_flag = '0'
o.status in ('submitted', 'noticed', 'delivered') and coalesce(d.delivered_quantity, 0) > 0
) as sales_order_count, ( select coalesce(sum(coalesce(d.delivered_quantity, 0) * coalesce(d.unit_price, 0)), 0) from inv_sales_order o inner join inv_sales_detail d on d.order_id = o.order_id left join inv_product p on p.product_id = d.product_id and p.del_flag = '0' left join inv_product_category c on c.category_id = p.category_id and c.del_flag = '0'
o.status in ('submitted', 'noticed', 'delivered') and coalesce(d.delivered_quantity, 0) > 0
) as sales_delivered_amount, ( select coalesce(sum(coalesce(d.returned_quantity, 0) * coalesce(d.unit_price, 0)), 0) from inv_sales_return r inner join inv_sales_return_detail d on d.return_id = r.return_id left join inv_product p on p.product_id = d.product_id and p.del_flag = '0' left join inv_product_category c on c.category_id = p.category_id and c.del_flag = '0'
r.status = 'returned' and coalesce(d.returned_quantity, 0) > 0
) as sales_return_amount, ( select coalesce(sum(abs(coalesce(l.change_quantity, 0)) * coalesce(l.cost_price, 0)), 0) from inv_stock_log l inner join inv_sales_order o on o.order_id = l.business_id left join inv_product p on p.product_id = l.product_id and p.del_flag = '0' left join inv_product_category c on c.category_id = p.category_id and c.del_flag = '0'
l.movement_type in ('sales_out', 'outbound_out') and l.business_type in ('sales', 'outbound') and coalesce(l.change_quantity, 0) < 0 and o.status in ('noticed', 'delivered')
) as sales_out_cost, ( select coalesce(sum(coalesce(l.change_quantity, 0) * coalesce(l.cost_price, 0)), 0) from inv_stock_log l inner join inv_sales_return r on r.return_id = l.business_id left join inv_product p on p.product_id = l.product_id and p.del_flag = '0' left join inv_product_category c on c.category_id = p.category_id and c.del_flag = '0'
l.movement_type in ('sales_return_in', 'sales_return') and l.business_type = 'sales_return' and coalesce(l.change_quantity, 0) > 0 and r.status = 'returned'
) as sales_return_cost ) report_base ) report_amounts

select p.product_id, p.product_code, p.product_name, p.spec, p.unit from inv_stock s inner join inv_product p on p.product_id = s.product_id and p.del_flag = '0'
and (p.product_code like concat('%', #{params.keyword}, '%') or p.product_name like concat('%', #{params.keyword}, '%'))
group by p.product_id, p.product_code, p.product_name, p.spec, p.unit order by p.product_code asc, p.product_id asc limit #{params.optionLimit}
